/ {
	#address-cells = <1>;
	#size-cells = <0>;

	pinctrl: pin-controller {
		compatible = "vnd,pinctrl";
		status = "okay";

		test_device0_default: test_device0_default {
			group1 {
				pinmux = <1>, <2>;
				bias-pull-up;
			};
			group2 {
				pinmux = <3>;
				drive-open-drain;
				bias-high-impedance;
			};
		};

		test_device0_sleep: test_device0_sleep {
			group1 {
				pinmux = <1>, <2>, <3>;
				low-power-enable;
			};
		};

		test_device0_f0: test_device0_f0 {
			group1 {
				pinmux = <4>;
				bias-pull-up;
			};
		};

		test_device0_f1: test_device0_f1 {
			group1 {
				pinmux = <5>;
				bias-pull-down;
			};
		};

		test_device1_default: test_device1_default {
			group1 {
				pinmux = <10>;
				drive-push-pull;
				slew-rate = <1>;
			};
			group2 {
				pinmux = <11>, <12>;
				bias-disable;
			};
		};

		test_device1_sleep: test_device1_sleep {
			group1 {
				pinmux = <10>, <11>;
			};
		};

		test_device2_default: test_device2_default {
			group1 {
				pinmux = <20>;
			};
		};

		test_device3_default: test_device3_default {
			group1 {
				pinmux = <30>;
			};
		};
	};

	test_device0: test_device@0 {
		compatible = "vnd,device";
		reg = <0>;
		pinctrl-0 = <&test_device0_default>;
		pinctrl-1 = <&test_device0_sleep>;
		pinctrl-2 = <&test_device0_f0 &test_device0_f1>;
		pinctrl-names = "default", "sleep", "f0f1";
	};

	test_device1: test_device@1 {
		compatible = "vnd,device";
		reg = <1>;
		pinctrl-0 = <&test_device1_default>;
		pinctrl-1 = <&test_device1_sleep>;
		pinctrl-names = "default", "sleep";
	};

	test_device2: test_device@2 {
		compatible = "vnd,device";
		reg = <2>;
		pinctrl-0 = <&test_device2_default>;
		pinctrl-names = "default";
	};

	test_device3: test_device@3 {
		compatible = "vnd,device";
		reg = <3>;
		pinctrl-0 = <&test_device3_default>;
		pinctrl-names = "default";
		status = "disabled";
	};
};
